+
+it('shows an empty drawer without fetching aliases until creating the first alias', async () => {
+    const vault = { shareId: 'new-vault', content: { name: 'Personal' } } as any;
+    const getDefault = jest.fn().mockResolvedValue(undefined);
+    const createDefaultVault = jest.fn().mockResolvedValue(vault);
+    const getAllByShareId = jest.fn().mockResolvedValue([]);
+    const getUserAccess = jest.fn().mockResolvedValue({ plan: { AliasLimit: 10 } });
+    const getAliasOptions = jest.fn().mockResolvedValue({ mailboxes: [], suffixes: [] });
+    (usePassBridge as jest.Mock).mockReturnValue({
+        init: jest.fn().mockResolvedValue(true),
+        vault: { getDefault, createDefaultVault },
+        alias: { getAllByShareId, getAliasOptions },
+        user: { getUserAccess },
+    } as unknown as PassBridge);
+
+    const { result } = renderHook(() => usePassAliasesSetup());
+    await waitFor(() => expect(result.current.loading).toBe(false));
+    expect(result.current.hasAliases).toBe(false);
+    expect(getAllByShareId).not.toHaveBeenCalled();
+
+    await act(async () => {
+        await result.current.getAliasOptions();
+    });
+    expect(createDefaultVault).toHaveBeenCalledTimes(1);
+    expect(getAllByShareId).toHaveBeenCalledWith('new-vault', expect.any(Object));
+    expect(result.current.passAliasesVaultName).toBe('Personal');
+});
+
+it('clears cached aliases when initialization finds no vault', async () => {
+    const getDefault = jest
+        .fn()
+        .mockResolvedValueOnce({ shareId: 'old', content: { name: 'Old' } })
+        .mockResolvedValueOnce(undefined);
+    const bridge = {
+        init: jest.fn().mockResolvedValue(true),
+        vault: { getDefault },
+        alias: {
+            getAllByShareId: jest.fn().mockResolvedValue([{ item: { state: ItemState.Active, revisionTime: 1 } }]),
+        },
+        user: { getUserAccess: jest.fn().mockResolvedValue({ plan: { AliasLimit: 10 } }) },
+    } as unknown as PassBridge;
+    (usePassBridge as jest.Mock).mockReturnValue(bridge);
+
+    const { result: firstResult, unmount } = renderHook(() => usePassAliasesSetup());
+    await waitFor(() => expect(firstResult.current.hasAliases).toBe(true));
+    unmount();
+
+    const { result: secondResult } = renderHook(() => usePassAliasesSetup());
+    await waitFor(() => expect(secondResult.current.loading).toBe(false));
+    expect(secondResult.current.hasAliases).toBe(false);
+    expect(secondResult.current.passAliasesItems).toEqual([]);
+});
